export const envelope = [17, 16, 27];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;

  // Grid buffer to ensure single writes and deterministic output order
  const grid = new Map();

  function setBlock(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    if (!block) return;
    grid.set(`${x},${y},${z}`, block);
  }

  function getBlock(x, y, z) {
    return grid.get(`${x},${y},${z}`);
  }

  function groundY(x, z) {
    const raw = seatY + api.heightAt(x, z);
    return Math.max(0, Math.min(H - 1, Math.round(raw)));
  }

  function supportDown(x, startY, z, defaultBlock) {
    const gy = groundY(x, z);
    for (let y = startY - 1; y >= gy; y--) {
      if (!getBlock(x, y, z)) {
        setBlock(x, y, z, defaultBlock);
      }
    }
  }

  // Theme palette resolution with safe fallbacks
  const woodPlanks = api.theme?.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:spruce_log";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:spruce_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";

  const groundScree = api.theme?.ground?.scree || "minecraft:gravel";
  const groundBank = api.theme?.ground?.bank || "minecraft:coarse_dirt";
  const groundPavement = api.theme?.ground?.pavement || "minecraft:cobblestone";

  function withState(block, states) {
    const base = block.split("[")[0];
    const stateStr = Object.entries(states).map(([k, v]) => `${k}=${v}`).join(",");
    return `${base}[${stateStr}]`;
  }

  // -------------------------------------------------------------
  // 1. SHINGLE BEACH BERM & FROST-LOCKED SHORELINE FOUNDATION
  // -------------------------------------------------------------
  for (let z = 2; z <= 24; z++) {
    const u = (z - 13) / 10.5;
    const halfWidth = Math.max(1, Math.round(5.2 * Math.sqrt(Math.max(0, 1.0 - u * u))));
    const minX = Math.max(1, 8 - halfWidth - 2);
    const maxX = Math.min(W - 2, 8 + halfWidth + 3);

    for (let x = minX; x <= maxX; x++) {
      const gy = groundY(x, z);
      const hash = (x * 7 + z * 13 + (x ^ z)) % 10;
      let mat = groundScree;
      if (hash === 1 || hash === 2) mat = groundBank;
      else if (hash === 3 || hash === 4) mat = groundPavement;
      else if (hash === 5) mat = "minecraft:packed_ice";
      else if (hash === 6) mat = stonePrimary;

      setBlock(x, gy, z, mat);

      // Add a slight frost ridge under the ship's beached side
      if (x >= 7 && x <= 13 && z >= 6 && z <= 20 && gy + 1 < H) {
        if (hash >= 4) {
          setBlock(x, gy + 1, z, hash > 7 ? "minecraft:packed_ice" : groundScree);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 2. KEEL & BOTTOM ROCKER
  // -------------------------------------------------------------
  for (let z = 3; z <= 23; z++) {
    const u = (z - 13.0) / 10.5;
    const yk = Math.round(5.0 + 2.4 * (u * u) - 0.4 * u);
    const tiltShift = Math.round((yk - 5.0) * 0.35);
    const kx = 8 + tiltShift;

    setBlock(kx, yk, z, withState(woodLog, { axis: "z" }));
    supportDown(kx, yk, z, groundScree);

    // Keel bilge supports
    setBlock(kx - 1, yk, z, woodPlanks);
    supportDown(kx - 1, yk, z, groundScree);
    setBlock(kx + 1, yk, z, woodPlanks);
    supportDown(kx + 1, yk, z, groundScree);
  }

  // -------------------------------------------------------------
  // 3. SEWN-PLANK HULL SHELL (Tilted/Listed to Starboard +X)
  // -------------------------------------------------------------
  for (let z = 3; z <= 23; z++) {
    const u = (z - 13.0) / 10.5;
    if (Math.abs(u) > 1.02) continue;

    const R = 3.3 * Math.sqrt(Math.max(0, 1.0 - u * u));
    const yk = 5.0 + 2.4 * (u * u) - 0.4 * u;
    const h = 2.6 + 0.6 * (u * u);
    const yg = yk + h;

    const minY = Math.floor(yk);
    const maxY = Math.ceil(yg);

    for (let y = minY; y <= maxY; y++) {
      const tiltOffset = (y - 5.0) * 0.35;
      const xc = 8.0 + tiltOffset;
      const t = (y - yk) / h;
      if (t < -0.1 || t > 1.25) continue;

      const w = R * Math.min(1.15, Math.sqrt(Math.max(0.08, t)));
      const xPort = Math.round(xc - w);
      const xStbd = Math.round(xc + w);

      // Floor planking in hold bottom
      if (t <= 0.45) {
        for (let x = xPort; x <= xStbd; x++) {
          if (!getBlock(x, y, z)) {
            setBlock(x, y, z, woodPlanks);
            supportDown(x, y, z, groundScree);
          }
        }
      }

      // Port side (high side)
      if (y === maxY) {
        setBlock(xPort, y, z, withState(woodSlab, { type: "bottom" }));
      } else {
        const blk = (y === minY + 1) ? withState(woodStripped, { axis: "z" }) : woodPlanks;
        setBlock(xPort, y, z, blk);
      }
      supportDown(xPort, y, z, groundScree);

      // Starboard side (low beaching side)
      if (y === maxY) {
        setBlock(xStbd, y, z, withState(woodSlab, { type: "bottom" }));
      } else {
        const blk = (y === minY + 1) ? withState(woodStripped, { axis: "z" }) : woodPlanks;
        setBlock(xStbd, y, z, blk);
      }
      supportDown(xStbd, y, z, groundScree);
    }
  }

  // -------------------------------------------------------------
  // 4. INTERNAL RIBS, FRAMES & THWARTS (Sewn transverse beams)
  // -------------------------------------------------------------
  const ribZ = [5, 8, 11, 14, 17, 20];
  for (const rz of ribZ) {
    const u = (rz - 13.0) / 10.5;
    const yk = Math.round(5.0 + 2.4 * (u * u) - 0.4 * u);
    const R = 3.3 * Math.sqrt(Math.max(0, 1.0 - u * u));
    const xc = 8.0 + (yk + 1.5 - 5.0) * 0.35;
    const xPort = Math.round(xc - R * 0.85);
    const xStbd = Math.round(xc + R * 0.85);

    const thwartY = yk + 2;
    if (thwartY < H) {
      for (let x = xPort + 1; x < xStbd; x++) {
        setBlock(x, thwartY, rz, woodPlanks);
      }
      // Rib vertical cleats on inner hull
      setBlock(xPort, thwartY, rz, withState(woodStripped, { axis: "y" }));
      setBlock(xStbd, thwartY, rz, withState(woodStripped, { axis: "y" }));
    }
  }

  // -------------------------------------------------------------
  // 5. STEM POST (PROW - NORTH -Z) & STERN POST (+Z)
  // -------------------------------------------------------------
  // Stem curves up north toward Z = 1
  setBlock(8, 7, 3, withState(woodLog, { axis: "z" }));
  supportDown(8, 7, 3, groundScree);
  setBlock(8, 8, 3, withState(woodLog, { axis: "y" }));
  setBlock(8, 8, 2, withState(woodLog, { axis: "z" }));
  supportDown(8, 8, 2, groundScree);
  setBlock(8, 9, 2, withState(woodLog, { axis: "y" }));
  setBlock(8, 10, 2, withState(woodLog, { axis: "y" }));
  setBlock(8, 11, 2, withState(woodStripped, { axis: "y" }));
  // Carved prow beak / twin horn
  setBlock(8, 11, 1, withState(woodStairs, { facing: "south", half: "top" }));
  setBlock(8, 12, 1, woodFence);
  setBlock(8, 10, 1, withState(woodStairs, { facing: "north", half: "bottom" }));

  // Stern curves up south toward Z = 25
  setBlock(8, 7, 23, withState(woodLog, { axis: "z" }));
  supportDown(8, 7, 23, groundScree);
  setBlock(8, 8, 24, withState(woodLog, { axis: "z" }));
  supportDown(8, 8, 24, groundScree);
  setBlock(8, 9, 24, withState(woodLog, { axis: "y" }));
  setBlock(8, 10, 24, withState(woodStripped, { axis: "y" }));
  setBlock(8, 10, 25, withState(woodStairs, { facing: "north", half: "top" }));
  setBlock(8, 11, 25, woodFence);

  // Steering oar (Quarter rudder on starboard quarter)
  setBlock(11, 7, 22, woodFence);
  setBlock(11, 6, 23, withState(woodLog, { axis: "z" }));
  setBlock(11, 5, 24, withState(woodTrapdoor, { facing: "east", half: "top", open: "true" }));
  setBlock(11, 4, 25, withState(woodTrapdoor, { facing: "east", half: "top", open: "true" }));
  supportDown(11, 4, 25, groundScree);

  // -------------------------------------------------------------
  // 6. MAST, YARDARM, FURL ED SAIL & RIGGING
  // -------------------------------------------------------------
  const mastX = 9;
  const mastZ = 12;
  // Mast stepped on keel and rising through thwart
  for (let y = 5; y <= 14; y++) {
    setBlock(mastX, y, mastZ, withState(woodLog, { axis: "y" }));
  }
  setBlock(mastX, 15, mastZ, woodFence);
  setBlock(mastX, 13, mastZ - 1, "minecraft:lantern[hanging=true]");

  // Cross yardarm at Y = 12
  for (let x = 6; x <= 12; x++) {
    if (x !== mastX) {
      setBlock(x, 12, mastZ, withState(woodLog, { axis: "x" }));
    }
  }
  setBlock(5, 12, mastZ, woodFence);
  setBlock(13, 12, mastZ, woodFence);

  // Furled coarse wool sail lashed to yard
  for (let x = 6; x <= 12; x++) {
    setBlock(x, 11, mastZ, "minecraft:white_wool");
    setBlock(x, 11, mastZ + 1, withState(woodTrapdoor, { facing: "north", half: "top", open: "false" }));
  }
  setBlock(7, 10, mastZ, "minecraft:white_wool");
  setBlock(9, 10, mastZ, "minecraft:white_wool");
  setBlock(11, 10, mastZ, "minecraft:white_wool");

  // Rigging stays (Forestay, Backstay, Shrouds)
  setBlock(mastX, 13, 8, "minecraft:chain[axis=z]");
  setBlock(8, 10, 5, woodFence);
  setBlock(mastX, 13, 16, "minecraft:chain[axis=z]");
  setBlock(8, 9, 20, woodFence);
  setBlock(5, 9, mastZ, woodFence);
  setBlock(12, 8, mastZ, woodFence);

  // -------------------------------------------------------------
  // 7. TIMBER PROPPING STRUTS (SHORES - Port Side Support)
  // -------------------------------------------------------------
  // Strut 1 (Forward Port)
  setBlock(5, 7, 7, withState(woodLog, { axis: "x" }));
  setBlock(4, 6, 7, withState(woodLog, { axis: "x" }));
  setBlock(3, 5, 7, withState(woodLog, { axis: "y" }));
  setBlock(2, 4, 7, stoneWall);
  supportDown(2, 4, 7, stonePrimary);

  // Strut 2 (Midships Port)
  setBlock(4, 7, 13, withState(woodLog, { axis: "x" }));
  setBlock(3, 6, 13, withState(woodLog, { axis: "x" }));
  setBlock(2, 5, 13, withState(woodLog, { axis: "y" }));
  setBlock(1, 4, 13, stoneWall);
  supportDown(1, 4, 13, stonePrimary);

  // Strut 3 (Aft Port)
  setBlock(5, 7, 19, withState(woodLog, { axis: "x" }));
  setBlock(4, 6, 19, withState(woodLog, { axis: "x" }));
  setBlock(3, 5, 19, withState(woodLog, { axis: "y" }));
  setBlock(2, 4, 19, stoneWall);
  supportDown(2, 4, 19, stonePrimary);

  // -------------------------------------------------------------
  // 8. STARBOARD GANGPLANK & UNLOADING RAMP
  // -------------------------------------------------------------
  // Gangplank down from gunwale at Z = 15..16
  setBlock(11, 6, 15, woodPlanks);
  setBlock(12, 5, 15, withState(woodStairs, { facing: "west", half: "bottom" }));
  setBlock(13, 5, 15, woodPlanks);
  setBlock(14, 4, 15, withState(woodStairs, { facing: "west", half: "bottom" }));
  supportDown(14, 4, 15, groundScree);

  setBlock(11, 6, 16, woodPlanks);
  setBlock(12, 5, 16, withState(woodStairs, { facing: "west", half: "bottom" }));
  setBlock(13, 5, 16, woodPlanks);
  setBlock(14, 4, 16, withState(woodStairs, { facing: "west", half: "bottom" }));
  supportDown(14, 4, 16, groundScree);

  // Under-gangplank bracing
  setBlock(13, 4, 15, woodFence);
  supportDown(13, 4, 15, groundScree);
  setBlock(13, 4, 16, woodFence);
  supportDown(13, 4, 16, groundScree);

  // -------------------------------------------------------------
  // 9. CARGO IN THE HOLD & UNLOADED ON SHORE
  // -------------------------------------------------------------
  // Forward hold cargo (Z = 7..10)
  setBlock(8, 6, 7, "minecraft:decorated_pot");
  setBlock(9, 6, 7, "minecraft:decorated_pot");
  setBlock(8, 6, 8, "minecraft:raw_copper_block");
  setBlock(7, 6, 8, "minecraft:barrel[facing=up]");
  setBlock(8, 7, 8, "minecraft:hay_block[axis=y]");
  setBlock(7, 6, 9, "minecraft:raw_iron_block");
  setBlock(8, 6, 9, "minecraft:raw_copper_block");
  setBlock(9, 6, 9, "minecraft:white_wool");
  setBlock(7, 6, 10, "minecraft:hay_block[axis=y]");
  setBlock(8, 6, 10, "minecraft:barrel[facing=up]");

  // Aft hold cargo (Z = 16..19)
  setBlock(8, 6, 16, "minecraft:chest[facing=south]");
  setBlock(7, 6, 16, "minecraft:barrel[facing=up]");
  setBlock(9, 6, 16, "minecraft:raw_copper_block");
  setBlock(8, 6, 17, "minecraft:decorated_pot");
  setBlock(7, 6, 17, "minecraft:decorated_pot");
  setBlock(8, 7, 17, "minecraft:white_wool");
  setBlock(8, 6, 18, "minecraft:raw_iron_block");
  setBlock(9, 6, 18, "minecraft:barrel[facing=up]");

  // Beach cargo on Starboard shoreline (X = 12..15, Z = 9..14)
  const beachItems = [
    { x: 13, z: 9, blk: "minecraft:campfire[lit=false]" },
    { x: 14, z: 9, blk: stoneSlab },
    { x: 13, z: 10, blk: "minecraft:decorated_pot" },
    { x: 14, z: 10, blk: "minecraft:decorated_pot" },
    { x: 13, z: 11, blk: "minecraft:barrel[facing=up]" },
    { x: 14, z: 11, blk: "minecraft:hay_block[axis=y]" },
    { x: 13, z: 12, blk: "minecraft:raw_copper_block" },
    { x: 14, z: 12, blk: "minecraft:raw_copper_block" },
    { x: 13, z: 13, blk: "minecraft:raw_iron_block" },
    { x: 14, z: 13, blk: "minecraft:white_wool" },
    { x: 13, z: 14, blk: "minecraft:barrel[facing=up]" },
    { x: 14, z: 14, blk: "minecraft:decorated_pot" },
  ];

  for (const item of beachItems) {
    const gy = groundY(item.x, item.z) + 1;
    if (gy < H) {
      setBlock(item.x, gy, item.z, item.blk);
      supportDown(item.x, gy, item.z, groundScree);
    }
  }

  // Double stack some cargo on the beach
  const gy13_12 = groundY(13, 12) + 2;
  if (gy13_12 < H) {
    setBlock(13, gy13_12, 12, "minecraft:raw_copper_block");
  }
  const gy14_11 = groundY(14, 11) + 2;
  if (gy14_11 < H) {
    setBlock(14, gy14_11, 11, "minecraft:white_wool");
  }

  // -------------------------------------------------------------
  // 10. FROST, SEA-ICE RIME & DRIFTED SNOW DUSTING
  // -------------------------------------------------------------
  // Add ice rime patches at base of the tilted hull
  for (let z = 4; z <= 22; z += 2) {
    const gyPort = groundY(4, z);
    if (!getBlock(4, gyPort + 1, z)) {
      setBlock(4, gyPort + 1, z, "minecraft:packed_ice");
    }
    const gyStbd = groundY(12, z);
    if (!getBlock(12, gyStbd + 1, z)) {
      setBlock(12, gyStbd + 1, z, "minecraft:packed_ice");
    }
  }

  // Natural snow dusting on exposed top surfaces
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      // Find highest solid block in column
      let topY = -1;
      for (let y = H - 1; y >= 0; y--) {
        if (getBlock(x, y, z)) {
          topY = y;
          break;
        }
      }

      if (topY >= 0 && topY < H - 1) {
        const topBlock = getBlock(x, topY, z);
        // Do not place snow on fences, stairs, pots, or existing snow
        if (
          !topBlock.includes("fence") &&
          !topBlock.includes("stairs") &&
          !topBlock.includes("lantern") &&
          !topBlock.includes("chain") &&
          !topBlock.includes("decorated_pot") &&
          !topBlock.includes("campfire") &&
          !topBlock.includes("snow")
        ) {
          const snowHash = (x * 17 + z * 31 + topY * 7) % 5;
          if (snowHash === 0 || snowHash === 1) {
            setBlock(x, topY + 1, z, "minecraft:snow[layers=1]");
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 11. DETERMINISTIC EMISSION
  // -------------------------------------------------------------
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const key = `${x},${y},${z}`;
        if (grid.has(key)) {
          api.set(x, y, z, grid.get(key));
        }
      }
    }
  }

  return {
    name: "beached_trade_ship",
    seatY: seatY,
    anchors: {
      front: [8, 10, 0],
      door: [14, 5, 15],
      cargo: [13, 5, 12],
      mast: [9, 14, 12],
    },
  };
}

